INSERT INTO public.courses (title, university_id, degree_level, tuition_fee, duration, intake_months, overview, curriculum, entry_requirements, career_outcomes, offer_letter, entry_requirements_text) VALUES
  ('Bachelor of Computer Science (Interactive Media) with Honours', (SELECT id FROM public.universities WHERE name = 'UTeM University Malaysia' LIMIT 1), 'Bachelor', 3155, '4 years', '["Sep"]'::jsonb, 'The Bachelor of Computer Science (Interactive Media) with Honours program at UTeM University Malaysia prepares graduates with strong knowledge and advanced skills in multimedia and information technology. The program focuses on providing theoretical knowledge and practical skills in various aspects of information technology, including interactivity concepts, web development, animation, computer graphics, virtual reality, and computer game development. Graduates are equipped to develop high-quality interactive media products and multimedia applications that meet industry standards.

The Bachelor of Computer Science (Interactive Media) with Honours program at UTeM University Malaysia prepares graduates for careers in multimedia. They can work as web designers or developers, computer games designers, computer graphics designers, animators, digital audio video engineers, user interface designers, interactive media application developers, multimedia consultants, programmers, information system officers, or system analysts.

Thank you  for submitting your form to us. We will contact you as soon as possible to assist you on your university journey.', '[]'::jsonb, '{"min_gpa":"2.0","ielts":"5.5"}'::jsonb, '["The Bachelor of Computer Science (Interactive Media) with Honours program at UTeM University Malaysia prepares graduates for careers in multimedia. They can work as web designers or developers, computer games designers, computer graphics designers, animators, digital audio video engineers, user interface designers, interactive media application developers, multimedia consultants, programmers, information system officers, or system analysts."]'::jsonb, 'Fees Applies', 'Pass Matriculation / Foundation / STPM or equivalent.'),
  ('Bachelor of Computer Science (Software Development) with Honours', (SELECT id FROM public.universities WHERE name = 'UTeM University Malaysia' LIMIT 1), 'Bachelor', 3155, '4 years', '["Feb","Sep"]'::jsonb, 'The Bachelor of Computer Science (Software Development) with Honours program at UTeM University Malaysia prepares graduates with knowledge and skills in software engineering, project management, and quality control. Graduates are equipped to pursue careers in software development, software engineering, testing, and project management, meeting industry demands in the field of information technology and communication.

Graduates specialized in Software Engineering have the opportunity to work either in the Government or private sector. They could work as Information System Officer, System Analyst, Software Engineer, Software development Manager, Team member Software Quality Assurance, System Analyst, System Administrator, Software Tester or Software Development Consultant. Graduates have the opportunity to further their studies in Master and Doctorate level.

Thank you  for submitting your form to us. We will contact you as soon as possible to assist you on your university journey.', '[]'::jsonb, '{"min_gpa":"2.0","ielts":"5.5"}'::jsonb, '["Graduates specialized in Software Engineering have the opportunity to work either in the Government or private sector. They could work as Information System Officer, System Analyst, Software Engineer, Software development Manager, Team member Software Quality Assurance, System Analyst, System Administrator, Software Tester or Software Development Consultant. Graduates have the opportunity to further their studies in Master and Doctorate level."]'::jsonb, 'Fees Applies', 'Pass Matriculation / Foundation / STPM or equivalent.'),
